import type { Difficulty, QuizQuestion } from '../types';
import type { SourceId } from './sources';

const sources = {
  'design-principles': ['fowler-di','fowler-tell'],
  'object-modeling': ['js-classes','pg-constraints'],
  interfaces: ['fowler-di','js-classes'],
  'state-machines': ['w3c-scxml','pg-isolation'],
  'error-contracts': ['http-semantics','pg-constraints'],
  concurrency: ['pg-locks','pg-isolation'],
  collections: ['js-map','js-classes'],
  'testing-designs': ['fowler-unit','js-classes'],
} satisfies Record<string, SourceId[]>;

function q(number: number, topic: keyof typeof sources, prompt: string, answer: string, distractors: [string,string,string], explanation: string, difficulty: Difficulty = 'Medium'): QuizQuestion {
  const correct = (number - 1) % 4, options = [...distractors];
  options.splice(correct, 0, answer);
  return { id: `lld-q-${number.toString().padStart(3,'0')}`, topic, prompt, options, correct, explanation, difficulty, sourceIds: sources[topic] };
}

export const lowLevelDesignQuestions: QuizQuestion[] = [
  q(1,'design-principles','A parking system adds weekend pricing without changing ticket validity. Which boundary best localizes the change?','A supplied pricing policy used by the session owner',['A new subclass for every ticket identity','One shared function that also validates entry, writes storage, and sends emails','Public fields that let each caller recalculate and close a ticket'],'A supplied pricing policy isolates the varying arithmetic while the session owner continues to protect entry and closure rules. The policy can be a function if no richer lifecycle is needed. This boundary follows a concrete change scenario rather than an abstract preference for more classes. Callers still need defined units, valid ranges, and failure semantics.','Easy'),
  q(2,'design-principles','A constructor receives a repository object directly. What makes this dependency injection?','The collaborator is supplied rather than discovered inside the object',['The repository must be managed by a framework container','Every repository method is automatically atomic','The caller has transferred all authorization responsibilities to the repository'],'Dependency injection means a required collaborator is provided from outside the component. A constructor parameter is enough; a framework container is optional. Supplying the dependency makes construction and testing clearer, but does not establish storage semantics, authorization, or transaction guarantees. Those remain explicit parts of the collaborator contract and the boundaries where operations execute.'),
  q(3,'design-principles','Which change most clearly indicates that a class contains unrelated responsibilities?','A formatting-only change repeatedly modifies reservation ownership logic',['Several methods protect the same reservation lifecycle','One method calls a small pure pricing function','A reservation has both an identity and an expiration value'],'A formatting change should not ordinarily require editing the logic that grants or releases ownership. Repeated coupling of those changes suggests that independent decisions are interleaved. Cohesion is evaluated through plausible reasons to change, not method count alone. Several operations can belong together when they jointly protect one lifecycle and its invariants.'),
  q(4,'design-principles','A subtype rejects ordinary operations promised by its parent. What should be examined first?','Whether callers can substitute it while preserving the parent behavior contract',['Whether the subtype name is shorter','Whether every caller can catch all failures and pretend success','Whether the subtype has more private fields'],'Matching method names is not sufficient for behavioral substitution. If a subtype changes valid inputs, expected outcomes, units, or failure behavior, existing parent callers may break. Run shared contract traces against the implementations and inspect the actual guarantee required. Extra private fields and a pleasing hierarchy do not resolve a conflicting public contract.','Hard'),
  q(5,'design-principles','When should a fixed policy remain a plain function rather than become a strategy hierarchy?','When the function satisfies the required variation and lifecycle without added machinery',['Only when no tests are possible','Whenever the language supports classes','Only after creating subclasses for every possible future policy'],'The representation should follow demonstrated behavior and likely changes. A pure function can be an excellent pricing collaborator when it needs no independent state or lifecycle. Adding a hierarchy creates construction and substitution obligations without automatically improving clarity. Tests can exercise a function through the same meaningful inputs and outcomes used for an object policy.'),
  q(6,'design-principles','A repository interface accepts arbitrary SQL fragments from domain callers. What concern remains?','The boundary may still expose provider-specific storage decisions',['An interface always removes all coupling','SQL strings make the domain independent of the database','A fake repository now proves production isolation'],'An interface name does not eliminate coupling when its operations still require callers to understand provider-specific queries and errors. Shape the capability around business observations and updates, including conditional-write semantics where needed. A test adapter can validate that contract, while integration tests are still required for actual constraints, isolation, and durable behavior.','Hard'),
  q(7,'design-principles','Which assertion best protects behavior during a pricing refactor?','The same public session traces produce the same charges and rejection outcomes',['A private helper retains its old name','Every arithmetic method is invoked exactly once regardless of contract','The class diagram gains another box'],'Public traces preserve the observations callers depend on: charges, units, lifecycle changes, and rejection results. Requiring incidental helper names or calls can make a behavior-preserving refactor fail unnecessarily. Observable external effects may need ordering or duplicate assertions when those are contractual. Distinguish those obligations from internal implementation details that are free to change.'),

  q(8,'object-modeling','Two loaded reservation objects have the same stable reservation id but different JavaScript references. How should entity identity be evaluated?','Using the domain identity rule, not reference equality alone',['They must always be different reservations','Whichever object was allocated first is authoritative','JSON property order determines identity'],'Separate object reference from domain identity. Two materialized objects can describe the same reservation even though their references differ. A stable identifier supports that comparison, while version or lifecycle fields describe the current observation. Equality still needs a defined scope, such as tenant and facility; an identifier without its domain context is not automatically globally unique.','Easy'),
  q(9,'object-modeling','Which item is most naturally a value rather than an independently tracked entity in a simple locker model?','A validated size label used for compatibility',['A reservation with a changing lifecycle and stable id','A locker whose occupancy changes over time','A ticket retained across entry and checkout'],'A size label is typically distinguished by its contents and can be interchangeable with another equal label under the contract. Reservations, lockers, and tickets usually require identity across changes. This is a modeling choice rather than a rule about which JavaScript syntax to use. Values still need validation of their allowed representation and meaning.','Easy'),
  q(10,'object-modeling','A getter returns the mutable internal reservation map. What invariant risk does this introduce?','Callers can bypass the owner and alter protected state',['Maps cannot contain reservation ids','The getter automatically copies every nested value','Private method names prevent all outside mutations'],'Returning the actual mutable map creates another path for changing ownership without the normal checks. A caller could erase a reservation or change its quantity while capacity accounting remains unchanged. Use a deliberate read model or a sufficiently deep defensive copy. Private fields help only while their mutable contents are not leaked through another public reference.'),
  q(11,'object-modeling','Which equation should a single-pool inventory model preserve after each command?','Initial units equal available plus actively reserved plus committed units',['Initial units equal the number of reservation identifiers','Available units always equal initial units after commit','Released records contribute their quantities to active reservations forever'],'The equation expresses conservation across the three accounting categories. Committing a held quantity moves it from reserved to committed without restoring availability; releasing moves it back to available. Retained terminal identity records are not active reservations. Check this relationship after every trace prefix, because a final total can hide an intermediate double release or partial update.'),
  q(12,'object-modeling','A new outer array contains the same mutable reservation objects as an internal array. Is this a fully detached snapshot?','No; nested objects can still alias internal state',['Yes; any array spread recursively clones all objects','Yes; changing the outer array changes every object into a value','Only object property names determine aliasing'],'An outer copy separates array membership but not the references to its elements. Mutating a shared inner record can still change protected state. Choose a read model of immutable primitives, clone relevant nested values, or otherwise enforce the promised observation contract. Copying also has a memory cost that belongs in complexity and resource analysis.'),
  q(13,'object-modeling','What defines a useful aggregate boundary?','The state that one owner must change consistently to protect an invariant',['All objects that happen to have similarly spelled names','Every table in the whole deployment','Exactly one class and never any collaborators'],'A useful boundary follows the consistency requirement. Inventory accounting and its reservation record may need coordinated change, while unrelated presentation data does not. The owner can be implemented through a method locally and a transaction or conditional protocol persistently. A box around tables or a shared prefix in class names does not make their updates atomic.'),
  q(14,'object-modeling','Terminal reservation records remain after stock is released. Which memory statement is accurate?','Active stock can be bounded while retained identity history still grows',['Released state always frees all related memory automatically','Private fields guarantee constant memory for every trace','The available-unit count is the total number of stored records'],'Active resource usage and historical retention are different quantities. Keeping terminal records can prevent identity reuse and aid diagnostics, but memory then grows with retained identities, not merely held stock. A bounded trace makes that cost finite for a demo. A service needs explicit retention or admission rules compatible with the retry and audit contract.'),
  q(15,'object-modeling','Why is a read-only availability query not inherently poor object design?','It can be an intentional observation without delegating invariant-changing decisions',['Objects must never expose any data','A query always transfers mutation ownership to its caller','Every getter makes a model equivalent to a database schema'],'Useful collaboration often requires information. An intentional availability view can be appropriate when it does not leak mutable internals or force callers to reconstruct protected business mutations. The concern is where invariant-changing decisions occur, not the presence of every query. Evaluate the observation and ownership contract instead of mechanically removing all getters.'),
  q(16,'object-modeling','An amount in integer cents is compared with a dollar-valued threshold without conversion. What is the primary defect?','The comparison mixes semantic units despite compatible numeric representations',['Every integer comparison requires inheritance','The numbers become safe automatically because they are small','A private field removes the need for unit conversion'],'Compatible language types do not establish compatible units. A cents amount and a dollar threshold need an explicit conversion and defined rounding rule before comparison. Integer cents can avoid some decimal representation issues, but only within valid ranges and consistent units. Treat unit meaning as part of the value contract and test exact boundaries.','Hard'),
  q(17,'object-modeling','A class has private fields, but two processes each load and overwrite the same reservation. What guarantee is missing?','Coordination at the shared authoritative state boundary',['More underscores in field names','A different constructor name','A single local immutable string for the reservation id'],'Private fields protect access inside a particular runtime object; they do not coordinate separate processes or independently loaded state. A shared invariant needs storage-level conditional updates, suitable transactions or constraints, or another authoritative protocol. The identity rule is necessary but not enough. Test the real competing-writer mechanism rather than only a sequential object trace.','Hard'),

  q(18,'interfaces','Which reserve contract detail is missing from a signature containing only id and quantity?','Whether insufficient stock changes state and how retries are identified',['The preferred indentation width','The name of a private helper','The screen color for the result'],'A signature gives a small part of the contract. Callers also need valid units and ranges, mutation behavior on rejection, operation identity, and retry semantics. Insufficient stock should have a deliberate result and before-and-after state rule. Without these details, adapters with matching method names can behave incompatibly while still looking syntactically interchangeable.','Easy'),
  q(19,'interfaces','What benefit can returning a newly created receipt from a command provide?','It avoids requiring a second observation to recover the operation result',['It means commands never change state','It proves the operation is distributed exactly-once','It removes the need to define receipt identity'],'A command can return an intentional receipt describing its outcome. That often avoids a separate lookup that may race with later changes. Command/query separation is useful for making mutations visible, not a universal ban on command results. The receipt still requires a defined identity, observation boundary, and distinction from the object\'s later current state.','Easy'),
  q(20,'interfaces','A cache get refreshes access recency. Which interface description is honest?','Get has a documented recency side effect, while peek can be non-touching',['Every method named get must be observationally pure','Refresh behavior can remain unspecified because values are unchanged','Peek and get must always have identical mutation behavior'],'Recency affects later eviction and is observable even when the returned value does not change. Document the touch behavior in the public contract and provide a non-touching query if needed. Callers and substitute implementations must preserve that distinction. Hiding the mutation behind a familiar name makes traces and cache policy tests ambiguous.'),
  q(21,'interfaces','What should a clock capability specify beyond returning a number?','Its units, ordering assumptions, and meaning at expiry boundaries',['Only its class name','That tests must sleep until every deadline','That all numeric values are wall-clock timestamps'],'A clock value needs semantic context: integer milliseconds, a monotonic local tick, or a wall-clock instant are not automatically interchangeable. State any nondecreasing-time assumption and whether equality reaches expiry. Supplying the clock makes tests deterministic but does not define those rules by itself. Test before, at, and after the exact deadline under the chosen contract.'),
  q(22,'interfaces','A memory repository ignores duplicate identities although the real adapter rejects them. What is the testing risk?','Tests exercise a collaborator that violates the required contract',['Memory adapters are always stronger than databases','The domain is correct because no network was involved','A fake that accepts everything proves error handling'],'A useful fake must preserve the semantic outcomes the domain depends on, including duplicate identity and conflict behavior. Ignoring those cases can make incorrect operations pass unit tests. The fake still does not prove database isolation or durability; those need integration evidence. Keep contract equivalence and infrastructure guarantees as separate testing obligations.'),
  q(23,'interfaces','An interface named save hides whether it inserts, overwrites, or checks a version. What improves it most?','Specify the actual observation and conditional-update guarantees',['Rename every caller but leave semantics undefined','Catch every storage error and return success','Expose a global connection to every domain object'],'Callers need to know which changes are permitted and how conflicts or uncertain outcomes are reported. A deliberate insert or compare-version update contract is more useful than a generic save name with hidden behavior. Provider-specific mechanics can remain in an adapter, while the outcomes that change the caller\'s decision belong at the boundary.'),
  q(24,'interfaces','What belongs in a shared adapter contract suite?','The same valid-input traces and outcomes for duplicates, misses, and version conflicts',['Only whether the implementations share a class name','Only production credentials','Every adapter-specific query plan as a universal domain requirement'],'A contract suite checks the behavior clients require across implementations. Use the same traces for valid inputs, expected absence, identity conflicts, and conditional changes. Storage-specific query plans, locks, and crash durability require separate integration tests. Sharing an interface or returning similarly shaped objects does not establish that those meaningful outcomes are preserved.'),
  q(25,'interfaces','Why should a returned directory listing normally not expose its live internal child map?','Callers could mutate hierarchy state outside validated operations',['Maps cannot represent child identifiers','Sorting removes every possible alias automatically','A directory query is always forbidden in object-oriented code'],'The live map permits insertion or removal without parent-kind and lifecycle checks. Return an intentional view such as copied direct-child names in the documented order. Sorting alone is not a deep-copy mechanism and does not define which mutations are authorized. Keep useful queries while preserving the owner as the path for invariant-changing operations.'),
  q(26,'interfaces','A repository timeout occurs after an update may have committed. Which interface fact matters most?','How the caller can recover an authoritative outcome using a stable operation identity',['Whether the interface method is marked private','Whether a local boolean default can hide the failure','Whether increasing the retry count guarantees exactly one effect'],'After a timeout, absence of a response does not establish absence of a write. The contract should define recovery through an operation receipt or authoritative status observation and how parameters bind to identity. Blind retries or success defaults can produce duplicate or lost effects. The adapter boundary must expose uncertainty that materially changes the caller\'s next action.','Hard'),
  q(27,'interfaces','Does an injected method with the expected name prove full runtime contract compliance?','No; inputs, outcomes, lifecycle, and failure semantics still need validation and tests',['Yes; names alone prove transactional isolation','Yes; constructor injection automatically validates every external response','Only the file extension determines compatibility'],'A matching method name establishes little about behavior. A collaborator can return incorrect units, mutate shared inputs, reject valid requests, or expose unexpected failure categories. Injection improves construction and substitution opportunities, not semantic proof. Use guards where runtime data crosses a boundary and shared contract tests for the behavior that each supplied implementation promises.','Hard'),

  q(28,'state-machines','Which is an event rather than a lifecycle state?','Approve',['Approved','Submitted','Cancelled'],'An event requests behavior, while a state describes the current condition of the object. Approve may be accepted or rejected depending on the current state and other preconditions. Keeping these concepts separate helps create a transition table and explicit error outcomes. A label alone cannot establish that every path into a state was legal.','Easy'),
  q(29,'state-machines','An illegal transition is rejected. What should happen to the domain version in the stated approval model?','It remains unchanged',['It increments twice','It resets to zero regardless of history','It becomes the event name'],'The version represents accepted state changes in this model, so an illegal edge does not advance it. Rejection may still be retained as a command receipt under the separate identity policy. Test state, version, and result together, including a later valid command. Checking only the error tag can miss a corrupting hidden update.','Easy'),
  q(30,'state-machines','Submit is accepted, then cancel is accepted. An identical submit retry uses the original command id. What should a historical receipt API return?','The original submitted receipt while the current snapshot remains cancelled',['Execute submit again from cancelled','Overwrite the cached receipt with cancelled state','Delete the cancel command to restore the earlier state'],'A receipt answers what happened to a particular command, not what the object currently looks like. Replaying the stored submitted receipt is consistent with a later cancelled snapshot. The retry must not repeat the transition or rewrite history. Bind identity to the event parameters and distinguish the historical result from an intentional current-state observation.'),
  q(31,'state-machines','Which history is most useful for diagnosing rejected requests?','Requested commands paired with their accepted or rejected results',['Only the final state label','Only names of classes involved','Only commands that happened to succeed'],'Requested-command history preserves attempts that had no domain effect and their reasons for rejection. Accepted-transition history serves a different purpose and can be stored separately. A final state may be reached by several histories and cannot explain an out-of-turn request or stale update. Choose the retained observations according to replay, audit, privacy, and memory requirements.'),
  q(32,'state-machines','Why should victory be checked before draw on a full grid board?','The last placement may complete a winning line and must not be misclassified',['Draws are impossible on a full board','The last player always wins regardless of lines','Winning lines are only relevant before the last move'],'A board becoming full does not exclude a winning final placement. Under the stated game rules, a completed winning line determines victory before the no-empty-cells draw condition is considered. The ordering is observable in results and terminal metadata. A fixture for a last-cell win can expose a bug hidden by earlier wins or ordinary draw examples.'),
  q(33,'state-machines','What does run-to-completion processing conceptually separate in a state-chart model?','Completing an event and its enabled internal follow-up work before processing the next external event',['Waiting for every future event before any transition','Executing all external events simultaneously','Skipping internal transitions whenever the queue has another request'],'Run-to-completion defines an event-processing boundary rather than permission to interleave arbitrary external requests midway through enabled internal work. Rich state-chart standards describe details beyond a simple transition table. A small educational workflow can borrow the explicit event boundary without claiming full standard compliance, nested-state behavior, parallel regions, or infrastructure-level transaction guarantees.'),
  q(34,'state-machines','Which test evidence is strongest for a lifecycle table?','All legal edges and representative forbidden histories with exact state and version observations',['One successful path to the final state','A diagram with every state colored differently','Only a constructor test'],'Legal-edge coverage and forbidden histories challenge both the transition graph and its mutation rules. Include repetition, stale observations, terminal-state requests, and exact intermediate versions. A happy path does not establish that shortcuts are rejected or failures leave state unchanged. The graph representation is useful because it makes those obligations inspectable and guides focused examples.'),
  q(35,'state-machines','When might state objects be preferable to one small transition table?','When states own substantial distinct behavior that benefits from that boundary',['Whenever an enum has at least two labels','When every state can implement meaningless operations that always throw','Only because state tables cannot reject illegal edges'],'A table is often enough for a compact lifecycle. State objects can help when behavior differs substantially by state and that division makes responsibility clearer. They also add construction and substitution obligations. Evaluate the actual variation and public capabilities rather than assuming more classes improve correctness; either representation still needs validated transitions and persistent coordination when required.'),
  q(36,'state-machines','A new command has both a stale version and an otherwise illegal event. What determines the returned rejection?','The documented validation order of the protocol',['Whichever error happens to have a shorter string','The number of private fields','A universal rule that all state machines must choose the same error'],'Multiple failed conditions need a deliberate precedence rule when the error is observable. The reference approval protocol checks a new identity\'s expected version before its transition edge, so it reports stale first. Another protocol can choose differently if documented consistently. Preserve that behavior in adapters and tests rather than relying on incidental implementation branch order.','Hard'),
  q(37,'state-machines','Adding undo to a move history requires which design decision?','Whether undo targets the last requested command or the last accepted placement and how terminal state is recomputed',['Only reversing the final winner string','Automatically refunding every unrelated external effect','Deleting one arbitrary cell without inspecting history'],'Requested history can include rejected commands that never changed the board. Undo semantics must identify the intended accepted effect and update turn, victory, and draw consistently. External effects may require compensation rather than reversal. A retained array makes replay possible but does not define a safe undo contract or its authorization and failure boundaries.','Hard'),

  q(38,'error-contracts','A valid reservation asks for three units when only two remain. How is this best categorized?','A business rejection with a documented non-mutation rule',['Malformed integer syntax','Guaranteed infrastructure outage','Success with a silently reduced quantity'],'The request can satisfy the input domain yet be impossible in current state. Treat insufficient stock as a deliberate business outcome and preserve accounting. Malformed shape belongs to boundary validation, while infrastructure uncertainty is another category. Silently reducing quantity changes the caller\'s requested operation and requires a different explicitly agreed contract, not a convenient fallback.','Easy'),
  q(39,'error-contracts','An empty file is read successfully. Which result preserves its meaning?','A content result containing an empty string',['A not-found fallback because the content is falsy','A storage outage category','Deletion of the file to simplify the response'],'Empty content and absent file are distinct observations. A tagged content result can carry the empty string without confusing it with a missing record. Similar issues occur with zero cache values and empty lists. Validate existence separately from value truthiness and test these cases so useful boundary inputs do not become success-shaped or absence-shaped fallbacks.','Easy'),
  q(40,'error-contracts','What should normally precede irreversible state publication?','Validation of preconditions and computation of the proposed next state',['Marking success before checking inputs','Ignoring collaborator errors','Removing all operation identifiers'],'Validate the conditions that can be checked before publishing the domain change. Compute a proposed price or transition before closing a session when failure must leave it active. This does not make external effects reversible. Identify the commit boundary and any subsequent uncertainty explicitly, including provider outcomes and recovery records, instead of assuming an in-memory rollback can erase every effect.'),
  q(41,'error-contracts','Why is a broad catch that returns success dangerous after an unexpected storage failure?','It fabricates an outcome that the implementation cannot establish',['It makes all failures transactional automatically','It preserves every provider guarantee','It provides sufficient operator diagnostics by itself'],'A failure may mean no effect, a committed effect with a lost response, or a partial operation requiring recovery. Returning success without evidence conceals those distinctions and can mislead callers into dropping necessary work. Surface unexpected faults through the standard error and diagnostic boundary, while mapping known business rejections deliberately and avoiding sensitive payloads in logs.'),
  q(42,'error-contracts','A notification fails after a reservation commits. What is the first question to answer?','Which state is authoritative and how delivery or reconciliation is recovered',['Whether the reservation can be silently forgotten','Whether the notification handler can claim a successful delivery','Whether the caller should invent a new reservation every time'],'Separate the committed domain effect from downstream delivery. Define which result is authoritative, what intent was recorded, and how an incomplete notification is retried or reconciled. A transactional outbox may address durable intent when required. Neither an in-memory callback nor a broad retry loop proves exactly-once delivery or prevents duplicate allocation without a suitable operation identity.'),
  q(43,'error-contracts','A nonempty directory removal is rejected. What should be checked beyond the error tag?','That children and parent still exist unchanged and a later valid operation works',['That the directory name becomes shorter','That every descendant is removed despite rejection','That the root is also removed'],'A rejection test should assert non-mutation and continued valid behavior. The catalog\'s nonrecursive contract preserves the directory and descendants when it returns not-empty. Checking only a tag can miss partial deletion that corrupts later operations. Follow the rejected command with a meaningful query or valid child deletion and compare the entire state view.'),
  q(44,'error-contracts','Which recovery claim about compensation is accurate?','A compensation is another fallible operation, not automatic rollback of an external effect',['Compensation can never fail','It removes the need to record the original operation','It always restores every observer to the prior world state'],'An external effect may already be visible, and reversing or offsetting it requires another operation with its own authorization, failures, and uncertain response. Record identities and outcomes needed for reconciliation. Do not describe compensation as equivalent to rolling back a local transaction. Its acceptable business result and remaining temporary inconsistencies must be part of the recovery design.'),
  q(45,'error-contracts','How should expected absence differ from an unavailable datastore when callers need different behavior?','Use a deliberate not-found outcome for absence and an explicit infrastructure error for unavailability',['Return the same empty object for both','Always treat both as success','Treat unavailability as proof that the object was deleted'],'Absence can be a normal business observation, while an unavailable datastore means the observation could not be completed reliably. Collapsing both into not-found can trigger incorrect recreation or loss of work. Preserve categories that change the caller\'s decision, and define the appropriate diagnostic boundary. A small interface can still communicate these essential distinctions without leaking arbitrary provider details.'),
  q(46,'error-contracts','A new rejection code is added to an operation previously documented as success or missing. What must be evaluated?','Compatibility with callers that assumed the original closed set of outcomes',['Only whether the new string is unique','Whether a generic success default can hide it','Whether source files are in alphabetical order'],'Public error categories are part of the API contract. A caller may have exhaustively handled the original outcomes and now need a new retry, user message, or escalation path. Evaluate compatibility, rollout, and adapter behavior rather than treating error strings as internal decoration. Tests should preserve existing results and verify the newly introduced branch intentionally.','Hard'),
  q(47,'error-contracts','What does a timeout alone establish about a command that may have committed remotely?','Only that a timely response was not received, not whether the effect occurred',['The effect definitely never occurred','The effect definitely occurred exactly once','The operation identity should be discarded immediately'],'A timeout reports a communication observation, not authoritative knowledge of the business effect. The command may have committed before the response was lost. Recover using the defined operation identity or status protocol and bind retries to compatible parameters. Claiming either failure-with-no-effect or success-with-one-effect without evidence hides the uncertainty the caller needs to handle.','Hard'),

  q(48,'concurrency','Two writers both read one available space before either updates it. What is the problem?','The invariant spans an uncoordinated check-and-update sequence',['Each individual read must have returned invalid data','The class needs a longer name','Reading twice automatically makes allocation atomic'],'Both observations can be correct at their own instants while the combined updates assign the same resource twice. Protect the entire invariant-changing operation at the authoritative shared boundary. A second unchecked read merely shifts the timing window. The appropriate conditional update, transaction, constraint, or lock depends on how ownership is represented and where competing writers meet.','Easy'),
  q(49,'concurrency','What can a process-local mutex protect directly?','Operations that coordinate through the same local mutex',['Every independent database client automatically','All server replicas regardless of communication','All future operations after that process restarts'],'A local mutex coordinates participants sharing that mutex and runtime state. Another process or database writer can bypass it entirely. Persistent shared ownership therefore requires coordination at the storage or another authoritative boundary. This does not make local locks useless; it means their guarantee must match the scope of the invariant and actual participants.','Easy'),
  q(50,'concurrency','Why can JavaScript code with an await still suffer a stale-observation race?','Another operation may change shared state before the awaited operation resumes',['Await creates a database transaction automatically','Only languages without classes can race','Private fields stop every other callback from running'],'An asynchronous pause can separate an observation from a later mutation. Other callbacks or external writers may change the relevant state during that interval. A single event loop does not make the whole business operation atomic across awaits. Define ownership and version or locking checks at the actual shared boundary, and test a deliberately controlled competing history.'),
  q(51,'concurrency','Which evidence establishes real storage-level exclusive allocation most directly?','Competing transactions against the actual constraint or coordination mechanism',['Only a sequential in-memory trace','Only a diagram containing a lock symbol','Only the existence of a version field'],'A sequential model can validate lifecycle rules but contains no simultaneous writers. Exercise the actual transactional or conditional mechanism under forced overlap and assert exactly one owner, conserved capacity, and visible loser behavior. Keep the test reproducible. A version field is useful only when the comparison and update are protected at the boundary where writers converge.'),
  q(52,'concurrency','Two resource locks can be acquired in opposite orders. What design change reduces one common deadlock risk?','Use a consistent acquisition order and a deliberate contention policy',['Remove every timeout and wait forever','Add a third arbitrary lock with no ordering','Assume all lock modes are mutually compatible'],'A consistent order removes a common cycle where each operation holds one resource and waits for another. It does not eliminate every possible deadlock or fault, so define abort, timeout, and retry behavior as appropriate. Keep critical sections bounded and inspect the actual database or runtime semantics. Lock naming alone does not establish those properties.'),
  q(53,'concurrency','A conditional update finds that the stored version no longer matches the caller expectation. Which result is appropriate?','A visible conflict or defined retry path without overwriting the newer state',['An unconditional overwrite to preserve apparent success','Resetting the stored version to the caller value','Treating the mismatch as proof that no other writer exists'],'The mismatch means the operation\'s observation is stale under the optimistic protocol. Preserve the newer state and return the documented conflict or retry outcome. Retrying may require re-reading and revalidating the whole operation, not blindly repeating only the last write. Test the losing writer\'s behavior and ensure versions advance according to accepted changes.'),
  q(54,'concurrency','Why is holding a resource lock during an unrelated slow network call often undesirable?','It extends contention and failure exposure beyond the minimum invariant-changing work',['Network calls always release all database locks','A longer critical section guarantees fewer failures','It makes an external provider part of the same atomic transaction automatically'],'Keeping locks while waiting on uncontrolled remote latency increases contention and complicates timeout recovery. When the invariant permits it, record a deliberate state or durable intent under coordination and handle downstream work separately. Do not simply move work outside the lock without examining what must remain consistent. The transaction and provider boundaries still need an explicit failure model.'),
  q(55,'concurrency','What must be considered when a transaction is aborted for a serialization conflict?','Whether the complete transaction needs a bounded retry with revalidated observations',['Whether its last result can be silently reported as success','Whether replaying only an arbitrary final statement preserves every invariant','Whether deleting the operation identity avoids all duplicates'],'An aborted transaction did not complete its intended atomic changes. Under the chosen database isolation protocol, recovery may require rerunning the transaction and its observations with a bounded policy. External effects and operation identities need separate care so retries do not duplicate work. Follow the database\'s documented semantics and test actual conflict behavior rather than assuming a generic retry is sufficient.'),
  q(56,'concurrency','A lock is acquired on one existing row. What should not be assumed without further analysis?','That every possible absent row matching a broader predicate is also protected',['That the existing row is part of the database','That the query returned a row','That the operation used a transaction'],'Locking an existing row protects the documented interactions with that row; it does not automatically serialize every predicate involving missing or future records. Choose schema constraints, isolation, and a coordination protocol suited to the actual invariant. Inspect the relevant database semantics and force the competing insertion or ownership history in integration tests. A generic row-lock label can otherwise overstate protection.','Hard'),
  q(57,'concurrency','Which PostgreSQL lock-lifetime statement is the most careful?','Locks normally last until transaction end, with documented savepoint-rollback behavior',['Every lock disappears immediately after SELECT returns','Locks always persist forever after process restart','Savepoint rollback never affects any acquired lock'],'PostgreSQL documents lock lifetime at the transaction boundary and exceptions associated with rolling back to savepoints for locks acquired afterward. A caller should use the actual mechanism\'s semantics rather than infer lifetime from method completion. The distinction matters when reasoning about overlapping writers, rollback, and retries. Version-specific integration evidence remains separate from a sequential reference model.','Hard'),

  q(58,'collections','A cache stores zero for key a. What distinguishes that hit from absence?','Check key membership and return a tagged hit containing zero',['Treat every falsy value as missing','Delete the entry before interpreting it','Assume keys with zero values are invalid universally'],'Zero can be a valid cached value under the stated contract. Membership and value truthiness answer different questions, so check existence explicitly and return a tagged result. The same principle applies to empty file content or nullable values when permitted. Fixtures should include valid falsy data to prevent an accidental not-found fallback.','Easy'),
  q(59,'collections','Does LRU eviction alone establish a time-based freshness guarantee?','No; recency-based capacity eviction and TTL expiration are distinct policies',['Yes; every least-recently-used item is expired','Yes; the oldest access defines a universal validity deadline','Only the number of cache methods determines freshness'],'LRU chooses which entry to remove under capacity pressure; it does not specify how long a stored value remains valid. TTL introduces a clock and expiry contract with its own boundaries. A cache can implement either or both. Describe those policies separately and avoid presenting a bounded local eviction model as a production freshness-aware cache.','Easy'),
  q(60,'collections','Overwriting an existing JavaScript Map value without deleting its key does what to insertion order?','It retains that key position rather than making it newly inserted',['It always moves the key to the newest position','It randomly shuffles all keys','It sorts keys by numeric value'],'Map preserves the insertion position of an existing key when its value is replaced. An LRU implemented with insertion order therefore needs an explicit remove-and-reinsert step to refresh recency. Test replacement after other entries exist, not just a capacity-one cache. The policy consequence is observable in later eviction even when the updated value is correct.'),
  q(61,'collections','What does the JavaScript specification require about average Map access complexity?','Average sublinear access, not a mandated O(1) hash implementation',['Worst-case O(1) for every operation','Exactly O(n log n) for every lookup','No implementation may use hashing'],'Map\'s specification-level requirement is average sublinear access rather than one particular representation or constant-time hashing guarantee. Expected constant-time analysis can be useful under an explicitly stated hash-table model. Also account for scans, sorting, copied snapshots, and output size. A complexity claim should describe the actual assumptions, not convert a familiar collection name into an unsupported guarantee.'),
  q(62,'collections','At capacity two, put A, put B, get A, put C should evict which key in the stated LRU policy?','B',['A','C','Neither, because get adds capacity'],'The successful get makes A most recent, leaving B least recent. Inserting C then exceeds capacity and removes B. A missing lookup or non-touching peek would have different ordering consequences. State the touch policy and test the full command sequence, because checking only the returned values can miss an incorrect recency representation.'),
  q(63,'collections','What memory distinction matters for a reservation service that keeps terminal receipts?','Bounded active reservations do not by themselves bound retained history',['Receipts disappear automatically when a status changes','A Map can never grow beyond available inventory units','A private field has no memory cost'],'Terminal receipts can remain after resources are released, so history size may grow independently of active stock. Retention supports retry or audit semantics and needs its own policy or admission bound. Include the returned result history in a trace\'s memory analysis as well. A bounded demonstration does not establish unlimited service memory behavior.'),
  q(64,'collections','A reservation expires at time ten under an inclusive expiry rule. What happens to pickup at time ten?','It is already expired and must not retain active ownership',['It remains valid until a cleanup job happens to run','It is valid only if the code string is short','Every expiry rule universally includes another grace interval'],'An inclusive deadline means validity ends when the supplied time reaches the expiry. Logical checks must apply that boundary even when physical cleanup is lazy or asynchronous. A background job alone cannot define correctness for the intervening requests. Use an explicit clock model and test before, at, and after the deadline under the documented rule.'),
  q(65,'collections','For a cache capped at thirty-two entries, why might an array implementation be defensible?','Its bounded linear operations can be simpler to verify while meeting the actual requirement',['Arrays guarantee constant-time arbitrary-key lookup','The capacity bound removes the need to explain complexity','A linked list is illegal in a cache'],'Representation should match workload and clarity requirements. A small bounded array can have acceptable linear searches and fewer ownership invariants than a custom map/list structure. State the O(capacity) per-operation cost and output memory. A more sophisticated representation may become justified as scale or latency requirements change, but complexity alone does not make it the better scoped interview design.'),
  q(66,'collections','Why can expiry cleanup alone fail to bound limiter memory under arbitrary new client keys?','Many distinct keys can remain active within the same current window',['Cleanup always removes active counters immediately','The quota for one client is also a bound on the number of clients','Strings cannot be Map keys'],'Expiry removes stale records, not an arbitrary number of currently active identities. A burst of distinct clients can still grow state. A hard active-key admission limit or other deliberately specified resource policy is needed for that stronger bound. Capacity rejection has different semantics from exhausting one client\'s quota and should be visible to callers.','Hard'),
  q(67,'collections','Which cost must be included when returning a sorted detached reservation snapshot?','Materializing the output and sorting it under a stated runtime or comparison model',['Only one dictionary lookup regardless of record count','No memory because the snapshot is read-only','A language-mandated constant-time sort'],'A detached snapshot allocates its returned records, and sorting adds work according to the actual or assumed runtime model. Read-only observations are not free merely because they do not mutate the owner. JavaScript does not mandate one sort implementation or complexity. Account for output size and state any comparison-sort or expected dictionary assumptions explicitly.','Hard'),

  q(68,'testing-designs','Which fixture construction best avoids circular verification?','Write expected outcomes independently of the implementation being tested',['Call solve to generate all expected outputs','Treat any returned JSON as success','Skip intermediate states whenever the final class exists'],'Generating expected values from the same implementation only proves self-agreement and can preserve the same bug in both sides of the assertion. Specify small outcomes by hand or use a simpler independent oracle with a defined domain. Include result order, final state, boundaries, and relevant non-mutation checks. Test volume does not replace independence.','Easy'),
  q(69,'testing-designs','What makes an expiry test deterministic without waiting in real time?','Supply a controllable clock or explicit trace time',['Sleep for an arbitrary long interval','Use the actual wall clock and ignore occasional failures','Remove expiry from the contract'],'Supplying time makes the boundary reproducible and the test fast. The contract still needs units, ordering assumptions, and an inclusive or exclusive expiry rule. Test the same sequence at chosen before, exact, and after values. A fake clock verifies local timing decisions; it does not by itself establish distributed clock synchronization or persistence behavior.','Easy'),
  q(70,'testing-designs','Which sequence is particularly useful for detecting duplicated inventory release?','Reserve, release, and release the same identity again',['Construct the class once and inspect its name','Reserve without inspecting any later state','Only query unrelated product metadata'],'The repeated release challenges whether terminal state prevents restoring capacity twice. Assert each tagged result and the conservation equation after every prefix, then attempt another valid reservation. A final error tag alone may miss accounting corruption. Stateful histories expose defects that isolated method tests with freshly constructed objects can fail to exercise.'),
  q(71,'testing-designs','Is a unit test required to mock every collaborating pure object?','No; the useful behavioral boundary may include a small real object cluster',['Yes; any real collaborator makes it impossible to be a unit test','Only class names determine test isolation','Mocks automatically make all interface guarantees correct'],'Unit boundaries vary by the behavior being tested. A small cluster with real pure collaborators can be fast, deterministic, and easier to understand than many interaction mocks. Use doubles where controlling external effects or failures adds value. Neither solitary nor sociable testing automatically proves correctness; meaningful assertions and faithful collaborator contracts remain necessary.'),
  q(72,'testing-designs','What can a sequential versioned workflow trace establish directly?','Its specified state, receipt, and version semantics for the supplied command order',['Atomicity across independent database transactions','Durability after a real process crash without storage','The absence of every possible overlapping-writer defect'],'Sequential traces can validate legal and illegal transitions, replayed receipts, versions, and non-mutation. They do not contain actual simultaneous writers or durable storage. Keep that evidence label visible and add real integration tests for the mechanism that provides the stronger promise. A simulated expected-version check is valuable without being a production compare-and-swap guarantee.'),
  q(73,'testing-designs','Why run repeated calls on the same reference function with the same input trace?','To detect hidden global state or accidental state leakage across executions',['To make expected outputs depend on random clocks','To prove every future language implementation is identical','To bypass input validation automatically'],'A solve harness should create fresh per-call model state when that is its contract. Repeating traces can reveal a retained global counter, shared map, or mutable fixture that changes later results. Compare inputs before and after as well. These checks target a specific execution guarantee and complement, rather than replace, domain invariants and independent expected outcomes.'),
  q(74,'testing-designs','Which test should verify that a database uniqueness rule prevents two persistent owners?','An integration test exercising the actual rule with competing operations',['Only a fake repository that accepts both writes','Only an array-based sequential oracle','Only a method-name assertion'],'The guarantee belongs at the authoritative database boundary, so exercise that mechanism under controlled overlap. Assert the committed ownership and the visible losing outcome, not merely which request finished first. A domain fake can preserve the logical duplicate contract but cannot prove the actual schema and transaction behavior. Keep those distinct forms of evidence in the test plan.'),
  q(75,'testing-designs','An internal pure helper is renamed during a behavior-preserving refactor. Which failure suggests an overly coupled test?','A test fails only because it asserted the old helper name',['A public charge changes units unexpectedly','An invalid transition starts mutating state','A duplicate external effect appears'],'Tests should normally protect the contract rather than incidental internal naming. A renamed pure helper can preserve every required input and outcome, so asserting its name creates unnecessary refactor friction. Observable side effects or ordering may legitimately need stronger assertions. Distinguish implementation details from those contractual guarantees before weakening or strengthening a test.'),
  q(76,'testing-designs','A random-trace oracle finds a failure. What makes the evidence reproducible and actionable?','Retain the deterministic seed and minimize the failing command history',['Discard the command order and keep only the largest count','Replace the expected result with whatever solve returned','Use a new random seed until the failure disappears'],'Preserve enough information to reproduce the same valid-domain history, then reduce it to a small counterexample without changing the demonstrated failure. A deterministic seed helps, but the minimized explicit trace is often easiest to inspect and retain as a regression fixture. Do not modify the oracle to agree with the defective implementation merely to make the test pass.','Hard'),
  q(77,'testing-designs','Which statement most accurately reports passing reference-example checks?','The implementation agrees with the specified examples under the stated sequential model',['The application is certified production-safe under all workloads','Every design decision has received independent expert approval','The code necessarily achieves hiring readiness'],'Passing examples is bounded evidence about specific observations and an execution model. It does not establish universal correctness, production concurrency, provider reliability, human editorial review, or hiring outcomes. Combine independent fixtures with invariants, oracles, and appropriate integration tests. State remaining limits plainly so users understand what was verified and what still requires further evidence.','Hard'),
];
